  console.log(`  ║   Databricks: ${db.configured ? '✓ Connected' : '✗ Not configured'}                    ║`);
  console.log('  ║                                                   ║');
  console.log('  ╚═══════════════════════════════════════════════════╝');
  console.log('');
});

